// Kapso agrupa mensajes (búfer): body.data = [ { message, conversation, phone_number_id }, ... ]
// Valida origen, ignora salientes y junta el lote. Notas de voz: usa la transcripción de Kapso.
// Imágenes (y audios sin transcripción) van a «medios» para que Gemini los entienda.
const PERMITIDO = 'TU_PHONE_NUMBER_ID'; // phone_number_id del negocio
const MAX_MEDIOS = 3;   // tope por lote, para cuidar el costo
const limpiar = (s, n) => String(s || '').replace(/[\u0000-\u0008\u000b-\u001f\u007f]/g, '').trim().slice(0, n);
const body = $json.body ?? $json;
const items = Array.isArray(body.data) ? body.data : [body];
const textos = [], ids = [], medios = [];
let from = '', pnid = '', nombre = '';

for (const it of items) {
  const msg = it.message ?? {};
  const k = msg.kapso ?? {};
  if (k.direction && k.direction !== 'inbound') continue;
  const p = String(it.phone_number_id || it.conversation?.phone_number_id || '');
  if (p && p !== PERMITIDO) continue;
  pnid = p || pnid;
  from = msg.from || it.conversation?.phone_number || from;
  nombre = it.conversation?.contact_name || nombre;
  if (msg.id) ids.push(String(msg.id));

  const tipo = msg.type || 'text';
  const url = k.media_url || k.media_data?.url || '';
  const mime = String(k.media_data?.content_type || msg[tipo]?.mime_type || '').split(';')[0];

  if (tipo === 'text') {
    const t = limpiar(msg.text?.body || k.content, 1000);
    if (t) textos.push(t);
  } else if (tipo === 'audio') {
    const t = limpiar(k.transcript?.text, 1000);
    if (t) textos.push('(nota de voz) ' + t);
    else if (url && medios.length < MAX_MEDIOS) {
      textos.push('{{MEDIO_' + medios.length + '}}');
      medios.push({ tipo: 'audio', url, mime: mime || 'audio/ogg', caption: '' });
    } else textos.push('[El cliente envió una nota de voz que no pude escuchar]');
  } else if (tipo === 'image') {
    const caption = limpiar(msg.image?.caption, 500);
    if (url && medios.length < MAX_MEDIOS) {
      textos.push('{{MEDIO_' + medios.length + '}}');
      medios.push({ tipo: 'imagen', url, mime: mime || 'image/jpeg', caption });
    } else textos.push('[El cliente envió una imagen que no pude ver]' + (caption ? ' con el texto: ' + caption : ''));
  } else if (tipo === 'interactive' || tipo === 'button') {
    const t = limpiar(msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || msg.button?.text || k.content, 300);
    if (t) textos.push(t);
  } else if (tipo === 'reaction') {
    continue; // una reacción (👍) no necesita respuesta
  } else {
    const caption = limpiar(msg[tipo]?.caption, 500);
    textos.push('[El cliente envió un mensaje de tipo "' + tipo + '" que no puedo abrir]' + (caption ? ' con el texto: ' + caption : ''));
  }
}

const to = String(from).replace(/\D/g, '');
if (!to || textos.length === 0) return [];

return [{ json: {
  text: textos.join('\n').slice(0, 3000),
  to, nombre: String(nombre).slice(0, 80),
  phoneNumberId: pnid || PERMITIDO,
  message_id: ids[ids.length - 1] || ('sin-id-' + $execution.id),
  message_ids: ids,
  medios
} }];

// Texto para el agente: el lote original o los mensajes que llegaron mientras respondía.
const p = $input.first().json.pendientes;
const texto = Array.isArray(p) && p.length ? p.join('\n') : $('Normalizar mensaje').first().json.text;
return [{ json: { texto } }];

// CONFIGURACIÓN DEL NEGOCIO (editar aquí)
const TZ = 'America/Guayaquil';
// Horario por día: bloques [inicio, fin) en horas. Día sin bloques = cerrado.
// Horario de EliDental publicado en Instagram (21/9/2024): L-V 09:00-18:00, sábado 09:00-15:00.
const HORARIO = {
  lunes: [[9, 18]],
  martes: [[9, 18]],
  'miércoles': [[9, 18]],
  jueves: [[9, 18]],
  viernes: [[9, 18]],
  'sábado': [[9, 15]],
  domingo: []
};
const MAX_DIAS = 60;
// Servicios de EliDental (Loja). precio: null = la doctora lo confirma en la consulta.
const SERVICIOS = [
  { nombre: 'Consulta de valoración', precio: null },
  { nombre: 'Limpieza dental', precio: null },
  { nombre: 'Resina (calza)', precio: null },
  { nombre: 'Control de ortodoncia', precio: null },
  { nombre: 'Urgencia dental', precio: null }
];

const inp = $('Agenda (entrada interna)').first().json;
const fail = (error, mensaje) => [{ json: { valido: false, ok: false, error, mensaje } }];
const accion = String(inp.accion || 'turnos').trim().toLowerCase();
if (!['turnos', 'reservar'].includes(accion)) return fail('ACCION_INVALIDA', 'accion debe ser turnos o reservar');

const fecha = String(inp.fecha || '').trim();
if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha)) return fail('FECHA_INVALIDA', 'La fecha debe tener formato YYYY-MM-DD');
const dia = DateTime.fromISO(fecha, { zone: TZ });
if (!dia.isValid) return fail('FECHA_INVALIDA', 'Esa fecha no existe');
const hoy = DateTime.now().setZone(TZ).startOf('day');
if (dia < hoy) return fail('FECHA_PASADA', 'Esa fecha ya pasó');
if (dia > hoy.plus({ days: MAX_DIAS })) return fail('FECHA_MUY_LEJANA', 'Solo agendamos hasta ' + MAX_DIAS + ' días adelante');
const nombreDia = ['lunes','martes','miércoles','jueves','viernes','sábado','domingo'][dia.weekday - 1];
const bloques = HORARIO[nombreDia] || [];
if (!bloques.length) return fail('DIA_CERRADO', 'El ' + nombreDia + ' no atendemos');
const APERTURA = Math.min(...bloques.map(b => b[0]));
const CIERRE = Math.max(...bloques.map(b => b[1]));

let servicio = null, hora = '', nombre = '';
if (accion === 'reservar') {
  const q = String(inp.servicio || '').trim().toLowerCase();
  servicio = SERVICIOS.find(s => s.nombre.toLowerCase() === q) || SERVICIOS.find(s => q && (s.nombre.toLowerCase().includes(q) || q.includes(s.nombre.toLowerCase())));
  if (!servicio) return fail('SERVICIO_INVALIDO', 'Servicios: ' + SERVICIOS.map(s => s.nombre).join(', '));
  hora = String(inp.hora || '').trim().slice(0, 5);
  if (/^\d:\d{2}$/.test(hora)) hora = '0' + hora;
  if (!/^([01]\d|2[0-3]):00$/.test(hora)) return fail('HORA_INVALIDA', 'La hora debe ser en punto, formato HH:00 (24h)');
  nombre = String(inp.nombre || '').trim().slice(0, 80);
  if (nombre.length < 2) return fail('FALTA_NOMBRE', 'Falta el nombre del paciente');
}

return [{ json: {
  valido: true, accion, fecha, dia: nombreDia, apertura: APERTURA, cierre: CIERRE, bloques,
  desde: dia.set({ hour: APERTURA }).toISO(), hasta: dia.set({ hour: CIERRE }).toISO(),
  hora, nombre, servicio: servicio?.nombre || '', precio: servicio?.precio ?? null,
  telefono: String(inp.telefono || '').replace(/\D/g, '')
} }];

// Turnos de 1 hora dentro de los bloques del día (Validar pedido) que no chocan con Google Calendar.
const TZ = 'America/Guayaquil';
const req = $('Validar pedido').first().json;
const dia = DateTime.fromISO(req.fecha, { zone: TZ });
const minimo = DateTime.now().setZone(TZ).plus({ minutes: 15 });

const ocupados = [];
for (const it of $input.all()) {
  const ev = it.json || {};
  if (!ev.start || ev.status === 'cancelled' || ev.transparency === 'transparent') continue;
  const ini = ev.start.dateTime ? DateTime.fromISO(ev.start.dateTime) : DateTime.fromISO(ev.start.date, { zone: TZ });
  const fin = ev.end?.dateTime ? DateTime.fromISO(ev.end.dateTime) : DateTime.fromISO(ev.end?.date || ev.start.date, { zone: TZ }).plus(ev.end?.date ? {} : { days: 1 });
  if (ini.isValid && fin.isValid) ocupados.push([ini, fin]);
}

const manana = [], tarde = [], libres = [];
for (let h = req.apertura; h < req.cierre; h++) {
  const t = dia.set({ hour: h, minute: 0, second: 0, millisecond: 0 });
  const f = t.plus({ hours: 1 });
  if (!req.bloques.some(([a, b]) => h >= a && h + 1 <= b)) continue; // fuera de horario (p. ej. almuerzo)
  if (t < minimo) continue;
  if (ocupados.some(([a, b]) => t < b && f > a)) continue;
  libres.push(t.toFormat('HH:mm'));
  (h < 12 ? manana : tarde).push(t.toFormat('HH:mm') + ' - ' + f.toFormat('HH:mm'));
}

const base = { fecha: req.fecha, dia: req.dia, manana, tarde };
if (req.accion === 'turnos') {
  return [{ json: { ok: true, crear: false, ...base, total: libres.length,
    mensaje: libres.length ? 'Turnos libres de 1 hora' : 'No hay turnos libres ese día' } }];
}
if (!libres.includes(req.hora)) {
  return [{ json: { ok: false, crear: false, error: 'HORA_NO_DISPONIBLE', ...base,
    mensaje: 'Esa hora ya no está libre. Ofrece otra de manana/tarde.' } }];
}
const inicio = dia.set({ hour: Number(req.hora.slice(0, 2)), minute: 0 });
return [{ json: { ok: true, crear: true, fecha: req.fecha, dia: req.dia, hora: req.hora,
  inicio: inicio.toISO(), fin: inicio.plus({ hours: 1 }).toISO(),
  titulo: '🦷 ' + req.servicio + ' - ' + req.nombre,
  descripcion: 'Paciente: ' + req.nombre + '\nTel: ' + req.telefono + '\nServicio: ' + req.servicio + (req.precio != null ? ' ($' + req.precio + ')' : '') + '\nAgendado por WhatsApp (Eli)',
  servicio: req.servicio, precio: req.precio, nombre: req.nombre } }];

// Seguimiento: el paciente escribió. Reinicia los seguimientos (o los detiene si no quiere más).
const n = $('Normalizar mensaje').first().json;
let s = {};
try { s = JSON.parse($json.seg || '{}') || {}; } catch (e) { s = {}; }
const NEGATIVO = /(no gracias|no me interesa|no me escriba|no me escribas|ya agend[eé]|ya tengo cita|no necesito)/i;
s.in = new Date().toISOString();
s.n = (s.n || 0) + 1;
s.paso = NEGATIVO.test(n.text || '') ? 'fin' : null;
s.pnid = n.phoneNumberId;
s.nombre = n.nombre || s.nombre || '';
return [{ json: { key: 'v4:seg:' + n.to, valor: JSON.stringify(s), ttl: 86400 } }];

// Seguimiento: Eli respondió. Guarda la hora y si en este turno se reservó o movió una cita.
const n = $('Normalizar mensaje').first().json;
let s = {};
try { s = JSON.parse($json.seg || '{}') || {}; } catch (e) { s = {}; }
const pasos = $('Agente version4').first().json.intermediateSteps || [];
const txt = x => (typeof x === 'string' ? x : JSON.stringify(x || ''));
const reservo = pasos.some(p => p.action?.tool === 'reservar_cita' && /"?reservada"?\s*:\s*true/.test(txt(p.observation)))
  || pasos.some(p => p.action?.tool === 'mover_cita' && !/error/i.test(txt(p.observation)));
const ahora = new Date();
s.out = ahora.toISOString();
if (!s.in) s.in = s.out;
if (!s.n) s.n = 1;
if (reservo) s.agendado = true;
s.pnid = s.pnid || n.phoneNumberId;
s.nombre = s.nombre || n.nombre || '';
// La clave vive hasta que se cierra la ventana de 24 h desde el último mensaje del paciente.
const ttl = Math.max(60, Math.round((new Date(s.in).getTime() + 86400000 - ahora.getTime()) / 1000));
return [{ json: { key: 'v4:seg:' + n.to, valor: JSON.stringify(s), ttl } }];

// Un ítem por imagen o audio, con la instrucción para Gemini.
const PROMPT_IMG = "Eres el apoyo de Eli, asistente de WhatsApp de un consultorio dental. Describe en español, en máximo 3 frases y sin inventar, lo que se ve en esta imagen que mandó un paciente y lo que le importa al consultorio (por ejemplo: diente roto, encía inflamada, radiografía, receta, comprobante de pago, captura de pantalla). Si hay texto escrito, cópialo. No des diagnósticos.";
const PROMPT_AUDIO = "Transcribe literalmente esta nota de voz en español. Responde solo con la transcripción.";
return ($('Leer webhook').first().json.medios || []).map((m, i) => ({ json: {
  i, tipo: m.tipo, url: m.url, mime: m.mime, caption: m.caption,
  prompt: m.tipo === 'audio' ? PROMPT_AUDIO : PROMPT_IMG + (m.caption ? ' El paciente escribió junto a la imagen: ' + m.caption : '')
} }));

// Une el texto del lote con lo que Gemini entendió de cada imagen o audio.
// Los demás nodos leen $('Normalizar mensaje'): aquí queda el mensaje final.
const base = $('Leer webhook').first().json;
const medios = base.medios || [];
let text = base.text;
if (medios.length) {
  const resp = $input.all();
  medios.forEach((m, i) => {
    const r = resp[i]?.json ?? {};
    const leido = String(r.candidates?.[0]?.content?.parts?.map(p => p.text || '').join(' ') || '').trim().slice(0, 1000);
    let t;
    if (m.tipo === 'audio') t = leido ? '(nota de voz) ' + leido : '[El cliente envió una nota de voz que no pude escuchar]';
    else t = leido ? '(imagen) ' + leido + (m.caption ? ' — el cliente escribió: ' + m.caption : '')
                   : '[El cliente envió una imagen que no pude ver]' + (m.caption ? ' con el texto: ' + m.caption : '');
    text = text.replace('{{MEDIO_' + i + '}}', t);
  });
}
const { medios: _, ...resto } = base;
return [{ json: { ...resto, text: text.slice(0, 3000) } }];

// Evento para Eli → CRM. Por ahora NO lleva el texto del mensaje (privacidad). Si algo falta, no manda nada.
// Se lee de «Leer webhook» (está justo antes de ¿Mensaje nuevo?): no espera la cadena de medios con Gemini.
const n = $('Leer webhook').first().json;
if (!n.to || !n.message_id) return [];
return [{ json: { tipo: 'mensaje_entrante', telefono: n.to, nombre_whatsapp: n.nombre || undefined, message_id: n.message_id, en: new Date().toISOString() } }];

// Respuesta que Eli acaba de mandar. Por ahora NO lleva el texto (privacidad). execution_id lleva el número de vuelta para que cada respuesta del bucle sea única.
const n = $('Normalizar mensaje').first().json;
if (!n.to) return [];
return [{ json: { tipo: 'mensaje_saliente', telefono: n.to, execution_id: $execution.id + '-' + $runIndex, en: new Date().toISOString() } }];

// Cita creada en Google Calendar (Crear evento devuelve el id del evento).
const r = $('Validar pedido').first().json;
const c = $('Calcular turnos (mañana / tarde)').first().json;
const ev = $input.first().json;
if (!ev.id || !r.telefono) return [];
return [{ json: { tipo: 'cita_reservada', telefono: r.telefono, gcal_event_id: ev.id, inicio: c.inicio, fin: c.fin, servicio: c.servicio, nombre: c.nombre } }];

// Eli → CRM: cambios de agenda que Eli hizo con mover_cita / cancelar_cita (van directo a Google Calendar).
// Lee los pasos del agente (intermediateSteps: action.tool, action.toolInput, observation) y cuenta SOLO las
// llamadas que no fallaron. Un ítem por evento; ninguno si no hubo cambios. No lleva texto del mensaje.
const n = $('Normalizar mensaje').first().json;
if (!n.to) return [];
let salida;
try { salida = $('Agente version4').itemMatching(0).json; } catch (e) { salida = $('Agente version4').last().json; }
const pasos = Array.isArray(salida?.intermediateSteps) ? salida.intermediateSteps : [];
const leer = (v) => { if (typeof v !== 'string') return v ?? null; try { return JSON.parse(v); } catch (e) { return null; } };
const fallo = (obs) => { const o = leer(obs); const l = Array.isArray(o) ? o : (o == null || o === '' ? [] : [o]); return l.length === 0 || l.some((x) => !x || typeof x !== 'object' || x.error); };
const eventos = new Map();
for (const p of pasos) {
  const tool = p?.action?.tool;
  if (tool !== 'mover_cita' && tool !== 'cancelar_cita') continue;
  if (fallo(p.observation)) continue;
  let a = leer(p.action.toolInput) ?? {};
  if (typeof a.input === 'string') a = leer(a.input) ?? a; else if (a.input && typeof a.input === 'object') a = a.input;
  const id = String(a.event_id ?? '').trim();
  if (!id) continue;
  if (tool === 'cancelar_cita') { eventos.set(id, { tipo: 'cita_cancelada', telefono: n.to, gcal_event_id: id }); continue; }
  const obs = leer(p.observation);
  const ev = Array.isArray(obs) ? obs[0] : obs;
  let inicio = ev?.start?.dateTime;
  let fin = ev?.end?.dateTime;
  if (!inicio && a.nueva_fecha && a.nueva_hora) {
    const d = DateTime.fromISO(a.nueva_fecha + 'T' + a.nueva_hora, { zone: 'America/Guayaquil' });
    if (d.isValid) { inicio = d.toISO(); fin = d.plus({ hours: 1 }).toISO(); }
  }
  if (!inicio) continue;
  if (!fin) fin = DateTime.fromISO(inicio).plus({ hours: 1 }).toISO();
  eventos.set(id, { tipo: 'cita_movida', telefono: n.to, gcal_event_id: id, inicio, fin });
}
return [...eventos.values()].map((json) => ({ json }));
